143	                        final Buffer recordedRequestBody = recordedRequest.getBody();
144	                        byte[] bodyBytes = new byte[(int) recordedRequestBody.size()];
145	
146	                        recordedRequestBody.readFully(bodyBytes);
147	                        recordedRequestBody.close();
