160	                    fields.forEachRemaining(field -> {
161	                        if (HttpHeaders.CONTENT_TYPE.equalsIgnoreCase(field.getKey())) {
162	                            assertEquals(
163	                                    "application/json", field.getValue().get(0).asText());
