33	/**
34	 * This receiver essentially instantiates a custom ClientHttpRequest that stores the request body via a subscriber
35	 * The BodyInserter instance from our original request inserts into this subscriber that we can then retrieve
36	 * using receiveValue.
37	 *
38	 * We do this so that the received value that we display to the user is exactly the same as
39	 * the body tht is sent over the wire
40	 */
41	public class BodyReceiver {
42	    private static final Object DUMMY = new Object();
43	
44	    private final AtomicReference<Object> reference = new AtomicReference<>(DUMMY);
45	
46	    public Object receiveValue(BodyInserter<?, ? extends ReactiveHttpOutputMessage> bodyInserter) {
47	        demandValueFrom(bodyInserter);
48	
49	        return receivedValue();
50	    }
51	
52	    private void demandValueFrom(BodyInserter<?, ? extends ReactiveHttpOutputMessage> bodyInserter) {
53	        final BodyInserter<Object, MinimalHttpOutputMessage> inserter =
54	                (BodyInserter<Object, MinimalHttpOutputMessage>) bodyInserter;
55	
56	        inserter.insert(
57	                MinimalHttpOutputMessage.INSTANCE, new SingleWriterContext(new WriteToConsumer<>(reference::set)));
58	    }
59	
60	    private Object receivedValue() {
61	        Object value = reference.get();
62	        reference.set(DUMMY);
63	
64	        Object validatedValue;
65	
66	        if (value == DUMMY) {
67	            throw new AppsmithPluginException(
68	                    AppsmithPluginError.PLUGIN_ERROR, "Value was not received, check if your inserter worked properly");
69	        } else {
70	            validatedValue = value;
71	        }
72	
73	        return validatedValue;
74	    }
